import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

def preprocess_image(image_path):
    """Preprocess image for better OCR results."""
    img = Image.open(image_path)
    # Convert to grayscale
    img = img.convert('L')
    # Increase contrast
    img = ImageOps.autocontrast(img)
    # Optionally scale up for better OCR
    width, height = img.size
    img = img.resize((width * 2, height * 2), Image.LANCZOS)
    return img

def extract_text_from_image(image_path):
    """Extract text from image using Tesseract OCR."""
    img = preprocess_image(image_path)
    # Try PSM 6 first (assume single uniform block of text)
    text = pytesseract.image_to_string(img, config='--psm 6')
    return text

def parse_date(text):
    """Extract date from receipt text and convert to YYYY-MM-DD format."""
    lines = text.split('\n')

    month_names = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12',
        'january': '01', 'february': '02', 'march': '03', 'april': '04',
        'june': '06', 'july': '07', 'august': '08', 'september': '09',
        'october': '10', 'november': '11', 'december': '12'
    }

    # First pass: look for explicit date patterns
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Pattern: DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

        # Pattern: DD/MM/YY or DD-MM-YY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                year_full = '20' + year if int(year) < 50 else '19' + year
                return f"{year_full}-{month}-{day}"

        # Pattern: YYYY/MM/DD
        match = re.search(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})', line)
