def parse_date(text):
    """Extract date from receipt text and convert to YYYY-MM-DD format."""
    # Common date patterns in receipts
    # Try various formats: DD/MM/YYYY, DD-MM-YYYY, YYYY-MM-DD, DD.MM.YYYY, etc.
    date_patterns = [
        r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})',  # DD/MM/YYYY or DD-MM-YYYY
        r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})',   # DD/MM/YY
        r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})',   # YYYY/MM/DD
        r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})',        # DD Mon YYYY
        r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{2})',        # DD Mon YY
    ]

    month_names = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12',
        'january': '01', 'february': '02', 'march': '03', 'april': '04',
        'june': '06', 'july': '07', 'august': '08', 'september': '09',
        'october': '10', 'november': '11', 'december': '12'
    }

    lines = text.split('\n')
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Try numeric date patterns
        for pattern in date_patterns[:3]:
            matches = re.findall(pattern, line)
            for match in matches:
                try:
                    if len(match) == 3:
                        p1, p2, p3 = match
                        p1, p2, p3 = p1.zfill(2), p2.zfill(2), p3

                        # Determine format
                        if len(p3) == 4:  # YYYY or DD/MM/YYYY
                            if int(p1) > 31:  # YYYY/MM/DD
                                year, month, day = p1, p2, p3
                            else:  # DD/MM/YYYY
                                day, month, year = p1, p2, p3
                        else:  # YY format
                            if int(p1) > 31:  # YY/MM/DD (unlikely)
                                year = '20' + p1 if int(p1) < 50 else '19' + p1
                                month, day = p2, p3
                            else:  # DD/MM/YY
                                day, month = p1, p2
                                year = '20' + p3 if int(p3) < 50 else '19' + p3

                        # Validate
                        if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                            return f"{year}-{month}-{day}"
                except:
                    continue

        # Try month name patterns
        for pattern in date_patterns[3:]:
            matches = re.findall(pattern, line, re.IGNORECASE)
            for match in matches:
                try:
                    day, month_str, year = match
                    month_str = month_str.lower()
                    if month_str in month_names:
                        month = month_names[month_str]
                        day = day.zfill(2)
                        if len(year) == 2:
                            year = '20' + year if int(year) < 50 else '19' + year
                        return f"{year}-{month}-{day}"
                except:
                    continue

    return None

def parse_total_amount(text):
    """Extract total amount from receipt text using keyword priority."""
    lines = text.split('\n')

    # Exclusion keywords
    exclusion_keywords = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

    def should_skip(line):
        """Check if line should be skipped based on exclusion keywords."""
        upper = line.upper()
        return any(kw in upper for kw in exclusion_keywords)

    def extract_amount(line):
        """Extract monetary amount from a line."""
        # Match amounts with optional comma separator
        # Patterns: 1234.56, 1,234.56, 1234.5, etc.
        patterns = [
            r'[\$RM\s]*(\d{1,3}(?:,\d{3})*\.\d{2})',  # 1,234.56 or 1234.56
            r'[\$RM\s]*(\d+\.\d{2})',                    # 1234.56
            r'[\$RM\s]*(\d+\.\d{1})',                    # 1234.5
            r'[\$RM\s]*(\d{1,3}(?:,\d{3})*)',           # 1234 or 1,234
        ]
        for pattern in patterns:
            matches = re.findall(pattern, line)
            for m in matches:
                try:
                    # Remove commas
                    val = m.replace(',', '')
                    float(val)  # Validate
                    return val
                except:
                    continue
        return None

    def format_amount(val):
        """Format amount to exactly two decimal places."""
        try:
            val = val.replace(',', '')
            return f"{float(val):.2f}"
        except:
            return None

    # Priority 1: GRAND TOTAL
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'GRAND TOTAL' in upper:
            if should_skip(line):
                continue
            amount = extract_amount(line)
            if amount:
                return format_amount(amount)
            # Check next line
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip(next_line):
                    amount = extract_amount(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 2: TOTAL RM, TOTAL: RM
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'TOTAL RM' in upper or 'TOTAL: RM' in upper:
            if should_skip(line):
                continue
            amount = extract_amount(line)
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip(next_line):
                    amount = extract_amount(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 3: TOTAL AMOUNT
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'TOTAL AMOUNT' in upper:
            if should_skip(line):
                continue
            amount = extract_amount(line)
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip(next_line):
                    amount = extract_amount(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 4: TOTAL, AMOUNT, TOTAL DUE, AMOUNT DUE, BALANCE DUE, NETT TOTAL, NET TOTAL
    keywords_p4 = ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT']
    for i, line in enumerate(lines):
        upper = line.upper()
        # Check for any of these keywords
        matched_kw = None
        for kw in keywords_p4:
            if kw in upper:
                matched_kw = kw
                break

        if matched_kw:
            if should_skip(line):
                continue
            amount = extract_amount(line)
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip(next_line):
                    amount = extract_amount(next_line)
                    if amount:
                        return format_amount(amount)

    return None

def main():
    img_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'

    # Get all image files
    image_files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tiff', '.bmp'))])

    results = []

    for img_file in image_files:
        img_path = os.path.join(img_dir, img_file)
        print(f"Processing: {img_file}")

        try:
            text = extract_text_from_image(img_path)
            print(f"  OCR Text (first 200 chars): {text[:200]}")

            date = parse_date(text)
            total_amount = parse_total_amount(text)

            print(f"  Date: {date}, Total: {total_amount}")

            results.append({
                'filename': img_file,
                'date': date,
                'total_amount': total_amount
            })
        except Exception as e:
            print(f"  Error: {e}")
            results.append({
                'filename': img_file,
                'date': None,
                'total_amount': None
            })

    # Create Excel file
    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    # Write header
    ws.append(['filename', 'date', 'total_amount'])

    # Write data rows sorted by filename
    for row in results:
        ws.append([row['filename'], row['date'], row['total_amount']])

