    """Extract text from image using Tesseract OCR."""
    img = preprocess_image(image_path)
    text = pytesseract.image_to_string(img, config='--psm 6')
    return text

def parse_date(text):
    """Extract date from receipt text and convert to YYYY-MM-DD format."""
    lines = text.split('\n')

    month_names = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12',
    }

    # Look for date patterns in each line
    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Pattern: DD/MM/YYYY or DD-MM-YYYY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

        # Pattern: DD/MM/YY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                year_full = '20' + year if int(year) < 50 else '19' + year
                return f"{year_full}-{month}-{day}"

        # Pattern: YYYY/MM/DD
        match = re.search(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})', line)
        if match:
            year, month, day = match.group(1), match.group(2), match.group(3)
            month = month.zfill(2)
            day = day.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

    # Try to extract date from invoice number
    for line in lines:
        match = re.search(r'(20\d{2})(\d{2})(\d{2})', line)
        if match:
            year, month, day = match.group(1), match.group(2), match.group(3)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

    return None

def should_skip_line(line):
    """Check if line should be skipped based on exclusion keywords."""
    upper = line.upper()

    # Skip lines that are primarily about these topics
    if re.search(r'\bSUBTOTAL\b', upper):
        return True
    if re.search(r'\bSUB\s+TOTAL\b', upper):
        return True
    if re.search(r'\bTAX\b', upper) and not re.search(r'TOTAL', upper):
        return True
    if re.search(r'\bGST\s+(?:REG|NO|ID|NUMBER|SUMMARY|AMOUNT)\b', upper):
