        return True
    if re.search(r'\bDEBIT\b', upper):
        return True
    if re.search(r'\bCHANGE\b', upper):
        return True
    if re.search(r'\bPAYMENT\b', upper):
        return True
    if re.search(r'\bROUND\b', upper):
        return True

    return False

