    """Extract monetary amount from a line."""
    # Look for amount patterns - prioritize amounts that appear after RM, $, or at end of line
    patterns = [
        r'RM\s*(\d{1,3}(?:,\d{3})*\.\d{2})',  # RM 1,234.56
        r'(\d{1,3}(?:,\d{3})*\.\d{2})\s*RM',  # 1,234.56 RM
