import os
import re
import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

def preprocess_image(image_path):
    """Preprocess image for better OCR results."""
    img = Image.open(image_path)
    img = img.convert('L')
    img = ImageOps.autocontrast(img)
    width, height = img.size
    img = img.resize((width * 2, height * 2), Image.LANCZOS)
    return img

def extract_text_from_image(image_path):
    """Extract text from image using Tesseract OCR."""
    img = preprocess_image(image_path)
    text = pytesseract.image_to_string(img, config='--psm 6')
    return text

def clean_ocr_number(s):
    """Clean OCR artifacts from a number string."""
    # Replace common OCR errors for digits
    # But be careful not to replace legitimate characters
    replacements = [
        ('o', '0'), ('O', '0'), ('l', '1'), ('I', '1'),
        ('S', '5'), ('s', '5'), ('B', '8'), ('G', '6'),
    ]
    # Only replace if it looks like a number (in context of digits/decimal/comma)
    result = s
    for old, new in replacements:
        # Only replace characters that are in positions that should be digits
        # This is a simplified approach
        pass  # Don't do blind replacement
    return s

def parse_date(text):
    """Extract date from receipt text and convert to YYYY-MM-DD format."""
    lines = text.split('\n')

    month_names = {
        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12',
    }

    for line in lines:
        line = line.strip()
        if not line:
            continue

        # Handle OCR errors in date (like 'a0' instead of '20')
        # Pattern: DD/MM/YYYY or DD-MM-YYYY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            # Fix common OCR errors in year
            year = year.replace('a', '2').replace('o', '0').replace('O', '0')
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31 and len(year) == 4:
                return f"{year}-{month}-{day}"

        # Pattern: DD/MM/YY
        match = re.search(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})', line)
        if match:
            day, month, year = match.group(1), match.group(2), match.group(3)
            day = day.zfill(2)
            month = month.zfill(2)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                year_full = '20' + year if int(year) < 50 else '19' + year
                return f"{year_full}-{month}-{day}"

        # Pattern: YYYY/MM/DD
        match = re.search(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})', line)
        if match:
            year, month, day = match.group(1), match.group(2), match.group(3)
            month = month.zfill(2)
            day = day.zfill(2)
            # Fix OCR errors
            year = year.replace('a', '2').replace('o', '0').replace('O', '0')
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

    # Try to extract date from invoice number
    for line in lines:
        match = re.search(r'(20\d{2})(\d{2})(\d{2})', line)
        if match:
            year, month, day = match.group(1), match.group(2), match.group(3)
            if 1 <= int(month) <= 12 and 1 <= int(day) <= 31:
                return f"{year}-{month}-{day}"

    return None

def should_skip_line(line):
    """Check if line should be skipped based on exclusion keywords."""
    upper = line.upper()

    if re.search(r'\bSUBTOTAL\b', upper):
        return True
    if re.search(r'\bSUB\s+TOTAL\b', upper):
        return True
    if re.search(r'\bTAX\b', upper) and 'TOTAL' not in upper:
        return True
    if re.search(r'\bGST\s+(?:REG|NO|ID|NUMBER|SUMMARY|AMOUNT)\b', upper):
        return True
    if re.search(r'\bSST\b', upper):
        return True
    if re.search(r'\bDISCOUNT\b', upper):
        return True
    if re.search(r'\bCHANGE\b', upper):
        return True
    if re.search(r'\bCASH\s+TENDERED\b', upper):
        return True
    if re.search(r'\bCASH\s+TEND\b', upper):
        return True
    if re.search(r'\bVISA\b', upper):
        return True
    if re.search(r'\bMASTERCARD\b', upper):
        return True
    if re.search(r'\bCREDIT\b', upper):
        return True
    if re.search(r'\bDEBIT\b', upper):
        return True
    if re.search(r'\bPAYMENT\b', upper):
        return True
    if re.search(r'\bROUND\b', upper):
        return True
    if re.search(r'\bSERV[\.\s]*CHARGE\b', upper):
        return True
    if re.search(r'\bCHANGE\b', upper):
        return True

    return False

def extract_amount_from_line(line, keyword=None):
    """Extract monetary amount from a line, preferring amount near keyword."""
    # Clean common OCR errors for amounts
    # Sometimes OCR reads 'ia' instead of '15', etc.
    cleaned_line = line

    # Find all amounts with 2 decimal places in the line
    amounts = re.findall(r'(\d+\.\d{2})', line)

    if not amounts:
        # Try with comma separator
        amounts = re.findall(r'(\d{1,3}(?:,\d{3})*\.\d{2})', line)
        amounts = [a.replace(',', '') for a in amounts]

    if not amounts:
        return None

    # If we have a keyword, try to find amount after the keyword
    if keyword:
        keyword_upper = keyword.upper()
        idx = line.upper().find(keyword_upper)
        if idx >= 0:
            # Look for amounts after the keyword
            rest = line[idx:]
            rest_amounts = re.findall(r'(\d+\.\d{2})', rest)
            if rest_amounts:
                return rest_amounts[0]

    # Return the last amount found (often the total is at the end)
    return amounts[-1] if amounts else None

def format_amount(val):
    """Format amount to exactly two decimal places."""
    try:
        val = val.replace(',', '')
        return f"{float(val):.2f}"
    except:
        return None

def parse_total_amount(text):
    """Extract total amount from receipt text using keyword priority."""
    lines = text.split('\n')

    # Priority 1: GRAND TOTAL
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'GRAND TOTAL' in upper:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, 'GRAND TOTAL')
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 2: TOTAL RM, TOTAL: RM
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'TOTAL RM' in upper or 'TOTAL: RM' in upper:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, 'RM')
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 3: TOTAL AMOUNT
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'TOTAL AMOUNT' in upper:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, 'TOTAL AMOUNT')
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 4: TOTAL DUE, AMOUNT DUE, BALANCE DUE, NETT TOTAL, NET TOTAL
    keywords_p4 = ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL']
    for i, line in enumerate(lines):
        upper = line.upper()
        matched_kw = None
        for kw in keywords_p4:
            if kw in upper:
                matched_kw = kw
                break

        if matched_kw:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, matched_kw)
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 5: TOTAL SALES INCL, TOTAL INCL, TOTAL AFTER
    keywords_p5 = ['TOTAL SALES INCL', 'TOTAL INCL', 'TOTAL AFTER', 'TOTAL SALES']
    for i, line in enumerate(lines):
        upper = line.upper()
        matched_kw = None
        for kw in keywords_p5:
            if kw in upper:
                matched_kw = kw
                break

        if matched_kw:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, matched_kw)
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 6: Generic TOTAL (but not SUBTOTAL)
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'TOTAL' in upper and 'SUB' not in upper:
            if should_skip_line(line):
                continue
            amount = extract_amount_from_line(line, 'TOTAL')
            if amount:
                return format_amount(amount)
            if i + 1 < len(lines):
                next_line = lines[i + 1]
                if not should_skip_line(next_line):
                    amount = extract_amount_from_line(next_line)
                    if amount:
                        return format_amount(amount)

    # Priority 7: Look for lines with just amount and "RM" (for receipts like 011.jpg)
    for i, line in enumerate(lines):
        upper = line.upper()
        if 'RM' in upper and 'TOTAL' not in upper:
            if should_skip_line(line):
                continue
            # Check if this might be a total line (short line with RM and amount)
            if re.search(r'RM\s*\d+\.\d{2}', line) or re.search(r'\d+\.\d{2}\s*RM', line):
                amount = extract_amount_from_line(line, 'RM')
                if amount:
                    return format_amount(amount)

    return None

def main():
    img_dir = '/app/workspace/dataset/img'
    output_file = '/app/workspace/stat_ocr.xlsx'

    image_files = sorted([f for f in os.listdir(img_dir) if f.lower().endswith(('.jpg', '.jpeg', '.png', '.tiff', '.bmp'))])

    results = []

    for img_file in image_files:
        img_path = os.path.join(img_dir, img_file)
        print(f"Processing: {img_file}")

        try:
            text = extract_text_from_image(img_path)

            date = parse_date(text)
            total_amount = parse_total_amount(text)

            # Debug output for problematic cases
            if date is None or total_amount is None:
                print(f"  DEBUG OCR (last 200 chars): {text[-200:]}")
                if date is None:
                    print(f"  WARNING: Date is None!")
                if total_amount is None:
                    print(f"  WARNING: Total is None!")

            print(f"  Date: {date}, Total: {total_amount}")

            results.append({
                'filename': img_file,
                'date': date,
                'total_amount': total_amount
            })
        except Exception as e:
            print(f"  Error: {e}")
            import traceback
            traceback.print_exc()
            results.append({
                'filename': img_file,
                'date': None,
                'total_amount': None
            })

    # Create Excel file
    wb = Workbook()
    ws = wb.active
    ws.title = "results"

    ws.append(['filename', 'date', 'total_amount'])

    for row in results:
        ws.append([row['filename'], row['date'], row['total_amount']])

    wb.save(output_file)
    print(f"\nResults saved to {output_file}")

if __name__ == '__main__':
    main()

